:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3c;
  --text: #e0e0e0;
  --accent: #4a9eff;
  --correct: #4caf50;
  --wrong: #f44336;
  --focus: #ffb74d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 28px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  text-align: center;
  color: var(--accent);
}

.instruction {
  text-align: center;
  font-size: 1rem;
  opacity: 0.8;
}

.target {
  font-size: 1.25rem;
  font-family: 'Courier New', monospace;
  background: #1a1a2a;
  padding: 16px;
  border-radius: 8px;
  word-break: break-word;
  min-height: 2.5em;
  border: 1px solid #3a3a4c;
}

.target .correct {
  color: var(--correct);
}

.target .wrong {
  color: var(--wrong);
  text-decoration: underline wavy var(--wrong);
}

.input {
  font-size: 1.15rem;
  font-family: 'Courier New', monospace;
  padding: 14px 16px;
  border-radius: 8px;
  border: 2px solid #3a3a4c;
  background: #1a1a2a;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s;
}

.input:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 183, 77, 0.3);
}

.input::placeholder {
  color: #6a6a7c;
}

.result {
  text-align: center;
  font-size: 1.2rem;
  font-weight: 600;
  min-height: 1.5em;
}

.btn {
  font-size: 1.1rem;
  font-weight: 600;
  padding: 14px 28px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  align-self: center;
}

.btn:hover {
  background: #3a8eef;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .target {
    font-size: 1.1rem;
    padding: 12px;
  }
  .input {
    font-size: 1rem;
    padding: 12px;
  }
  .btn {
    font-size: 1rem;
    padding: 12px 24px;
  }
}

const SENTENCE = 'The quick brown fox jumps over the lazy dog.';

const targetEl = document.getElementById('target-sentence');
const inputEl = document.getElementById('typing-input');
const resultEl = document.getElementById('result');
const restartBtn = document.getElementById('restart-btn');

let finished = false;

function renderTarget() {
  const typed = inputEl.value;
  const sentence = SENTENCE;
  let html = '';
  for (let i = 0; i < sentence.length; i++) {
    const char = sentence[i];
    const escaped = char === ' ' ? '&nbsp;' : char.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    if (i < typed.length) {
      const cls = typed[i] === char ? 'correct' : 'wrong';
      html += `<span class="${cls}">${escaped}</span>`;
    } else {
      html += `<span>${escaped}</span>`;
    }
  }
  targetEl.innerHTML = html;
}

function calculateAccuracy() {
  const typed = inputEl.value;
  const sentence = SENTENCE;
  if (typed.length === 0) return 100;
  let correct = 0;
  const len = Math.min(typed.length, sentence.length);
  for (let i = 0; i < len; i++) {
    if (typed[i] === sentence[i]) correct++;
  }
  return Math.round((correct / sentence.length) * 100);
}

function checkCompletion() {
  const typed = inputEl.value;
  if (typed.length >= SENTENCE.length) {
    finished = true;
    inputEl.disabled = true;
    const accuracy = calculateAccuracy();
    resultEl.textContent = `Accuracy: ${accuracy}%`;
    restartBtn.hidden = false;
    restartBtn.focus();
  }
}

function onInput() {
  if (finished) return;
  renderTarget();
  checkCompletion();
}

function restart() {
  finished = false;
  inputEl.value = '';
  inputEl.disabled = false;
  resultEl.textContent = '';
  restartBtn.hidden = true;
  renderTarget();
  inputEl.focus();
}

inputEl.addEventListener('input', onInput);
restartBtn.addEventListener('click', restart);

renderTarget();
inputEl.focus();
